style.css:
@-moz-document domain("chat.openai.com") {
body, html {
    background-color: #272822 !important;
    color: #f8f8f2 !important;
  }

  /* Fondo personalizado */
  body {
    background: url("https://c4.wallpaperflare.com/wallpaper/316/559/580/nebula-astronomy-4k-planets-cosmos-wallpaper-preview.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Translucidez para áreas principales */
  main, .text-base, .bg-gray-900, .dark .bg-gray-800,
  .bg-token-main-surface-primary, div[class*="message"] {
    background: rgba(0, 0, 0, 0.5) !important;
    backdrop-filter: blur(4px) !important;
    color: #ffffff !important;
  }

  /* Estilo de código */
  pre, code, code * {
    background: rgba(0, 0, 0, 0.6) !important;
    color: #00ffff !important;
    box-shadow: none !important;
    border: none !important;
  }

  /* Botón de enviar */
  .send-button {
    background-color: #f92672 !important;
    color: #f8f8f2 !important;
  }

  .send-button:hover {
    background-color: #ffb86c !important;
  }

  /* Encabezados con animación */
  h1 {
    font-size: 2rem !important;
    text-shadow: 0 2px 2px #000;
    animation: bounce_chatgpt 2s ease-in forwards;
    color: #cacaca !important;
  }

  @keyframes bounce_chatgpt {
    0% { transform: translateY(-45px); opacity: 1; }
    24% { opacity: 1; }
    40% { transform: translateY(-24px); }
    65% { transform: translateY(-12px); }
    82% { transform: translateY(-6px); }
    93% { transform: translateY(-4px); }
    25%, 55%, 75%, 87% { transform: translateY(0); }
    100% { transform: translateY(0); opacity: 1; }
  }

  /* Selección de texto */
  ::selection {
    background: #354700 !important;
    color: #fff !important;
  }

  ::-moz-selection {
    background: #354700 !important;
    color: #fff !important;
  }
}
